    if a.trackList.count != b.trackList.count || !zip(a.trackList, b.trackList).allSatisfy({ eqS50($0, $1) }) { bad.append("trackList") }
    if a.playlistList.count != b.playlistList.count || !zip(a.playlistList, b.playlistList).allSatisfy({ eqS50($0, $1) }) { bad.append("playlistList") }
    if a.subscriptionList.count != b.subscriptionList.count || !zip(a.subscriptionList, b.subscriptionList).allSatisfy({ eqS50($0, $1) }) { bad.append("subscriptionList") }
    return bad
}

